const twinCircleCastBase=castCraftedSkill;castCraftedSkill=(build,...args)=>{let result=twinCircleCastBase(build,...args);if(GEM[build.type]?.signature!==91)return result;let s=signatureSpells.at(-1);if(s?.mode!==91)return result;signatureSpells=signatureSpells.filter(v=>v.mode!==91||v===s);s.owner=p;s.rings=[{...s.origin},{x:s.x,y:s.y}];s.nextRing=1;s.beats=0;s.previous={x:p.x,y:p.y};s.pulse=0;s.target=null;if(dist(...s.rings)<120||!lineClear(...s.rings)||s.rings.some(r=>!passable(r.x,r.y,18))){signatureSpells=signatureSpells.filter(v=>v!==s);say('2つの印を120以上離して設置してください');}return result;};
const twinCircleStepBase=stepSignature;stepSignature=(s,dt)=>{if(s.mode!==91)return twinCircleStepBase(s,dt);if(dead||p.hp<=0||s.owner!==p)return false;if(paused||!Number.isFinite(dt)||dt<=0)return true;s.time=Math.round((s.time+dt)*1e6)/1e6;s.pulse=Math.max(0,s.pulse-dt);if(s.time>=6||dist(s.previous,p)>200||!lineClear(s.previous,p)||s.rings.some(r=>dist(p,r)>500||!lineClear(p,r)))return false;
 let mark=s.rings[s.nextRing],contact=projectileContact(s.previous,p,mark,35);if(s.time>=.3&&(contact!==null||dist(p,mark)<=35)){let impact=s.rings[1-s.nextRing];s.beats++;s.nextRing=1-s.nextRing;s.lastPulse=impact;s.pulse=.3;signatureArea(s,impact,110,1.3);playSignatureAudio(91,true,impact.x,impact.y);if(s.beats>=4)return false;}
 s.previous={x:p.x,y:p.y};return true;};
